(()=>{'use strict';let queued=false;function update(){queued=false;const shell=document.querySelector('#app-root>.app-shell');if(!shell)return;const isHome=document.documentElement.dataset.patiView==='home';const text=/tweet|soru/i.test(document.querySelector('.pati-feed-current')?.textContent||'');shell.classList.toggle('buchee-text-home',isHome&&text);if(isHome&&text){const main=document.querySelector('#main-content');const poll=main?.querySelector(':scope > .pati-daily-card');if(poll&&main.firstElementChild!==poll)main.prepend(poll)}}function queue(){if(!queued){queued=true;requestAnimationFrame(update)}}new MutationObserver(queue).observe(document.documentElement,{childList:true,subtree:true});document.addEventListener('click',e=>{if(e.target.closest('[data-pati-feed-choice]'))requestAnimationFrame(update)});document.addEventListener('DOMContentLoaded',queue);queue()})();